mapper.select:
select PTL_PORTFOLIO.PORTFOLIO_ID id, PTL_PORTFOLIO.PORTFOLIO_ID || ':' || PTL_PORTFOLIO.PORTFOLIO_NAME text from PTL_PORTFOLIO /* 多级法人改造 去除用户过滤 modify by caojin 2020/6/19 start*/ /*, PTL_PORTFOLIO_AUTHORITY where PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID */ /* 多级法人改造 去除用户过滤 modify by caojin 2020/6/19 end*/ where 1=1 and PTL_PORTFOLIO.PORTFOLIO_TYPE = #{manObiTypeFinProd}
and PTL_PORTFOLIO.PROFIT_TYPE='02'
and PTL_PORTFOLIO.PROFIT_TYPE in ('01','03')
and (PTL_PORTFOLIO.PORTFOLIO_ID like concat(concat('%',#{search}),'%') or PTL_PORTFOLIO.PORTFOLIO_NAME like concat(concat('%',#{search}),'%'))
and PTL_PORTFOLIO.PORTFOLIO_ID = #{initValue}

select count(1) from
PA_PRD_ISSUE_SCHEDULE where PROD_REGIST_CODE IS NOT NULL and
FINPROD_ID = #{finprodId}

select count(1) from
FIN_PRODUCT where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeProd} and
P_FINPROD_ID IS NULL and FINPROD_ID = #{finprodId}

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT_ADD.TMPL_ID tmplId, FIN_PRODUCT_ADD.ISSUE_STATUS IssueStatus, FIN_PRODUCT_ADD.TERM_TYPE period, FIN_PRODUCT.FINPROD_NAME finprodName, FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
FIN_PRODUCT_ADD.PORTFOLIO_ID ptlId,
FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT.OPERATION_TYPE operationType,
FIN_PRODUCT.LIQUIDATION_YESNO liquidationYesno, FIN_PRODUCT_ADD.PRD_DESIGN_ID prdDesignId,
FIN_RATE_INFO.INT_TYPE calcType, FIN_PRODUCT_ADD.IS_CYCLE isCycle, FIN_PRODUCT_ADD.IS_LAY isLay, FIN_PRODUCT_ADD.LAY_TYPE layType, FIN_PRODUCT_ADD.PROFIT_FLAG profitFlag, FIN_PRODUCT_ADD.DIRECT_DISCLOSURE_RISK_FLAG directDisclosureRiskFlag, FIN_PRODUCT.ENTRUST_TYPE entrustType, FIN_PRODUCT.ENTRUSTER entruster, FIN_RATE_INFO.RATE * 100 yield, PRD_SALE_PARAM.FIRST_SALE_VDATE firstSaleVdate, PRD_SALE_PARAM.FIRST_SALE_MDATE firstSaleMdate, FIN_PRODUCT.VDATE vdate, FIN_PRODUCT.MDATE mdate, FIN_PRODUCT_ADD.CLOSE_DAYS closeDays, FIN_PRODUCT.TERM_DAYS termDays, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_RATE_INFO.BASIS basis, FIN_PRODUCT.CCY ccy, FIN_PRODUCT_ADD.SALE_DEPARTMENT saleDepartment, FIN_PRODUCT_ADD.PUR_SPEED purSpeed, FIN_PRODUCT_ADD.RED_SPEED redSpeed, FIN_PRODUCT_ADD.IS_CASH_MANAGE isCashManage, Rep_Prod_Declare.IS_FHXGCP isFhxgcp, Rep_Prod_Declare.IS_YLLCCP isYllccp,
FIN_PRODUCT.ISSUE_TYPE issueType, FIN_PRODUCT_ADD.INVEST_NATURE investNature, FIN_PRODUCT_ADD.SALE_MODE saleMode,
PA_FIN_PRODUCT.DATA_SOURCE dataSource,/**数据来源**/
FIN_PRODUCT_TYPE.TYPE_6 prodSeries, FIN_PRODUCT_TYPE.TYPE_7 prodClass, FIN_PRODUCT_TYPE.TYPE_8 prodFeature, FIN_PRODUCT.TRUSTEE_ID trusteeId, PA_FIN_PRODUCT.exclusive_Prod exclusiveProd,
FIN_PRODUCT_ADD.prod_Manager prodManager, PA_FIN_PRODUCT.sale_Type saleType, PA_FIN_PRODUCT.same_Org sameOrg,
FIN_PRODUCT_ADD.investment_Cycle investmentCycle, PA_FIN_PRODUCT.TARGET_CUSTOMER_1 targetCustomer1, PA_FIN_PRODUCT.TARGET_CUSTOMER_2 targetCustomer2, PRD_SALE_PARAM.consignment_Flag consignmentFlag, PRD_SALE_PARAM.beforeEnd_Flag beforeEndFlag, PRD_SALE_PARAM.red_Flag redFlag, PRD_SALE_PARAM.defaultRed_Flag defaultRedFlag, PRD_SALE_PARAM.beforeEstablish_Flag beforeEstablishFlag, PRD_SALE_PARAM.continue_Flag continueFlag, (SELECT CRULE.PAY_TYPE FROM FIN_CASH_PAY_RULE CRULE WHERE CRULE.CASH_ID = FIN_CASH_INFO.CASH_ID AND ROWNUM = 1) payType, FIN_PRODUCT.is_Sus isSus, CHB_PRDRESIST_CODE.REG_CODE prodRegistCode, FIN_PRODUCT.LIQUIDATION_DATE liquidationDate, nvl(t.mdate,FIN_PRODUCT.VDATE) payintStartDate /*add by yejiejie 2019-3-8 start 产品期次*/ ,Rep_Prod_Declare.REP_FINPROD_STAGE repFinprodStage /*add by yejiejie 2019-3-8 start 产品期次*/
,nvl(Rep_Prod_Declare.REP_RISK_LEVEL,FIN_PRODUCT_ADD.RISK_LEVEL) riskLevel
,nvl(Rep_Prod_Declare.REP_FINPROD_INS_ID,REP_PROD_ISSUE.REP_BANK_PROD_CODE) repFinprodInsId ,FIN_CASH_INFO.BRANCH from FIN_PRODUCT left join CHB_PRDRESIST_CODE on FIN_PRODUCT.FINPROD_MARKET_ID = CHB_PRDRESIST_CODE.PRODID /*add by yejiejie 2019-3-8 start 中债报送表*/ left join Rep_Prod_Declare on FIN_PRODUCT.FINPROD_ID = Rep_Prod_Declare.rep_finprod_id /*add by yejiejie 2019-3-8 end 中债报送表*/ left join REP_PROD_ISSUE on FIN_PRODUCT.FINPROD_ID = REP_PROD_ISSUE.REP_FINPROD_ID left join BOK_POSITION_PRD on BOK_POSITION_PRD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and BOK_POSITION_PRD.CDATE = FIN_PRODUCT.MDATE left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PA_FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID left join FIN_PRODUCT_TYPE on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = #{branch}
left join FIN_RATE_INFO on FIN_CASH_INFO.CASH_ID = FIN_RATE_INFO.CASH_ID and (FIN_PRODUCT.VDATE IS NULL OR FIN_RATE_INFO.EFF_DATE = FIN_PRODUCT.VDATE) left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID left join ( select mdate,FINPROD_ID,row_number()over(partition by FINPROD_ID order by mdate desc) ro from TRD_FIN_PRODUCT_DEAL_TOTAL where ps=#{PS_ZJSX,jdbcType=VARCHAR} and FINPROD_TYPE2 = #{FINPROD_TYPE_LCCP,jdbcType=VARCHAR} and TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} and (IS_CANCEL = #{YES_NO_N} or IS_CANCEL is null)
and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) t on t.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and t.ro=1 where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_ID = #{finprodId}
and FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId}

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT_ADD.TMPL_ID tmplId, FIN_PRODUCT_ADD.ISSUE_STATUS IssueStatus, FIN_PRODUCT.FINPROD_NAME finprodName, FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
FIN_PRODUCT_ADD.PORTFOLIO_ID ptlId, /*PA_FIN_PRODUCT.DEAL_MODE dealMode,*/ FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT.OPERATION_TYPE operationType,
FIN_RATE_INFO.INT_TYPE calcType, FIN_PRODUCT_ADD.IS_CYCLE isCycle, FIN_PRODUCT_ADD.IS_LAY isLay, FIN_PRODUCT_ADD.LAY_TYPE layType, FIN_PRODUCT_ADD.PROFIT_FLAG profitFlag, FIN_PRODUCT.ENTRUST_TYPE entrustType, FIN_PRODUCT.ENTRUSTER entruster, FIN_RATE_INFO.RATE * 100 yield, PRD_SALE_PARAM.FIRST_SALE_VDATE firstSaleVdate, PRD_SALE_PARAM.FIRST_SALE_MDATE firstSaleMdate, FIN_PRODUCT.VDATE vdate, FIN_PRODUCT.MDATE mdate, FIN_PRODUCT_ADD.CLOSE_DAYS closeDays, FIN_PRODUCT.TERM_DAYS termDays, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_RATE_INFO.BASIS basis, FIN_PRODUCT.CCY ccy, FIN_PRODUCT_ADD.SALE_DEPARTMENT saleDepartment, FIN_PRODUCT_ADD.PUR_SPEED purSpeed, FIN_PRODUCT_ADD.RED_SPEED redSpeed,
FIN_PRODUCT.ISSUE_TYPE issueType, FIN_PRODUCT_ADD.INVEST_NATURE investNature, FIN_PRODUCT_ADD.SALE_MODE saleMode,
FIN_PRODUCT_TYPE.TYPE_6 prodSeries, FIN_PRODUCT_TYPE.TYPE_7 prodClass, FIN_PRODUCT_TYPE.TYPE_8 prodFeature, FIN_PRODUCT.TRUSTEE_ID trusteeId, PA_FIN_PRODUCT.exclusive_Prod exclusiveProd,
FIN_PRODUCT_ADD.prod_Manager prodManager, PA_FIN_PRODUCT.sale_Type saleType, PA_FIN_PRODUCT.same_Org sameOrg,
FIN_PRODUCT_ADD.investment_Cycle investmentCycle, PA_FIN_PRODUCT.TARGET_CUSTOMER_1 targetCustomer1, PA_FIN_PRODUCT.TARGET_CUSTOMER_2 targetCustomer2, PRD_SALE_PARAM.consignment_Flag consignmentFlag, PRD_SALE_PARAM.beforeEnd_Flag beforeEndFlag, PRD_SALE_PARAM.red_Flag redFlag, PRD_SALE_PARAM.defaultRed_Flag defaultRedFlag, PRD_SALE_PARAM.beforeEstablish_Flag beforeEstablishFlag, PRD_SALE_PARAM.continue_Flag continueFlag, (SELECT CRULE.PAY_TYPE FROM FIN_CASH_PAY_RULE CRULE WHERE CRULE.CASH_ID = FIN_CASH_INFO.CASH_ID AND ROWNUM = 1) payType, FIN_PRODUCT.is_Sus isSus, FIN_PRODUCT_ADD.prod_Regist_Code prodRegistCode, FIN_PRODUCT.LIQUIDATION_DATE liquidationDate, nvl(t.mdate,FIN_PRODUCT.VDATE) payintStartDate /*add by yejiejie 2019-3-8 start 产品期次*/ ,Rep_Prod_Declare.REP_FINPROD_STAGE repFinprodStage /*add by yejiejie 2019-3-8 start 产品期次*/
,Rep_Prod_Declare.REP_RISK_LEVEL riskLevel
,(select sum(a.AMOUNT) from PTL_SEC_POSITION a where a.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and a.cdate = (select max(b.cdate) from PTL_SEC_POSITION b where a.PORTFOLIO_ID = b.PORTFOLIO_ID ) ) mCusRevAmt
from FIN_PRODUCT /*add by yejiejie 2019-3-8 start 中债报送表*/ left join Rep_Prod_Declare on FIN_PRODUCT.FINPROD_ID = Rep_Prod_Declare.rep_finprod_id /*add by yejiejie 2019-3-8 end 中债报送表*/ left join BOK_POSITION_PRD on BOK_POSITION_PRD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and BOK_POSITION_PRD.CDATE = FIN_PRODUCT.MDATE left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PA_FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID
left join FIN_PRODUCT_TYPE on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = #{branch}
left join FIN_RATE_INFO on FIN_CASH_INFO.CASH_ID = FIN_RATE_INFO.CASH_ID and (FIN_PRODUCT.VDATE IS NULL OR FIN_RATE_INFO.EFF_DATE = FIN_PRODUCT.VDATE) left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID left join ( select mdate,FINPROD_ID,row_number()over(partition by FINPROD_ID order by mdate desc) ro from TRD_FIN_PRODUCT_DEAL_TOTAL where ps=#{PS_ZJSX,jdbcType=VARCHAR} and FINPROD_TYPE2 = #{FINPROD_TYPE_LCCP,jdbcType=VARCHAR} and TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} and (IS_CANCEL = #{YES_NO_N} or IS_CANCEL is null)
and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) t on t.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and t.ro=1 where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_ID = #{finprodId}
and FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId}

select CUSTOM_LEVEL customLevel, AMT_MIN amtMin, AMT_MAX amtMax, TERM_MAX termMax, TERM_MIN termMin, YIELD * 100 yield, REMARK remark, P_FINPROD_ID pFinprodId, VDATE vdate, nvl(PROD_STYLE,TERM_MAX) prodStyle, SALE_CHANNEL saleChannel, SALE_DEPARTMENT saleDepartment, TAR_CUSTOMER_TYPE tarCustomerType, IS_SALE isSale ,FINPROD_ID finprodId from PRD_LAYER_PARAM where 1=1
AND P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and P_FINPROD_ID in (select FINPROD_ID FROM FIN_PRODUCT where FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR} AND p_finprod_id is null)

select * from FIN_BASE_RULE_INFO
where FINPROD_ID = #{finProdId,jdbcType=VARCHAR}
AND BRANCH = #{finBrach,jdbcType=INTEGER}
AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}

	and EFF_DATE <= 
	to_date(#{queryDate}, 'yyyy-MM-dd')

ORDER BY EFF_DATE DESC

select FIN_BASE_RULE_INFO.BASE_RULE_ID baseRuleId, FIN_BASE_RULE_INFO.EFF_DATE effDate, FIN_BASE_RULE_INFO.RATE_TYPE rateType, FIN_BASE_RULE_INFO.RATE*100 rate, FIN_BASE_RULE_INFO.COEFFICIENT coefficient, FIN_BASE_RULE_INFO.INDEX_ID indexId, FIN_BASE_RULE_INFO.INDEX_SOURCE indexSource, FIN_BASE_RULE_INFO.SPREAD_RATE*100 spreadRate, FIN_BASE_RULE_INFO.RESET_TYPE resetType, FIN_BASE_RULE_INFO.BASE_RULE_TYPE baseRuleType, FIN_BASE_RULE_INFO.PUBLISH_TYPE publishType, FIN_BASE_RULE_INFO.RATE_LOWER*100 rateLower, FIN_BASE_RULE_INFO.RATE_LIMIT*100 rateLimit, FIN_BASE_RULE_INFO.FINPROD_ID finprodId from FIN_BASE_RULE_INFO where FINPROD_ID = #{finProdId,jdbcType=VARCHAR} AND BRANCH = #{finBrach,jdbcType=INTEGER} AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}
and EFF_DATE <= to_date(#{queryDate}, 'yyyy-MM-dd')
ORDER BY EFF_DATE DESC

select FIN_BASE_RULE_INFO.BASE_RULE_ID baseRuleId, FIN_BASE_RULE_INFO.EFF_DATE effDate, FIN_BASE_RULE_INFO.RATE_TYPE rateType, FIN_BASE_RULE_INFO.RATE*100 rate, FIN_BASE_RULE_INFO.COEFFICIENT coefficient, FIN_BASE_RULE_INFO.INDEX_ID indexId, FIN_BASE_RULE_INFO.INDEX_SOURCE indexSource, FIN_BASE_RULE_INFO.SPREAD_RATE*100 spreadRate, FIN_BASE_RULE_INFO.RESET_TYPE resetType, prd_layer_param.PROD_STYLE prodStyle, prd_layer_param.TERM_MAX investmentCycle, FIN_BASE_RULE_INFO.BASE_RULE_TYPE baseRuleType, FIN_BASE_RULE_INFO.PUBLISH_TYPE publishType, FIN_BASE_RULE_INFO.RATE_LOWER*100 rateLower, FIN_BASE_RULE_INFO.RATE_LIMIT*100 rateLimit, FIN_PRODUCT.VDATE vdate, FIN_BASE_RULE_INFO.FINPROD_ID finprodId from FIN_BASE_RULE_INFO, FIN_PRODUCT left join prd_layer_param on FIN_PRODUCT.FINPROD_ID = prd_layer_param.FINPROD_ID where FIN_BASE_RULE_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and (FIN_BASE_RULE_INFO.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} or prd_layer_param.P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR})
AND FIN_BASE_RULE_INFO.BASE_RULE_TYPE = #{baseRuleType,jdbcType=VARCHAR}
AND FIN_BASE_RULE_INFO.PUBLISH_TYPE = #{publishType,jdbcType=VARCHAR}
and FIN_BASE_RULE_INFO.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
and (FIN_BASE_RULE_INFO.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})

select LEV lev,
BASE_RULE_ID baseRuleId,
COEFFICIENT coefficient,
SPREAD_RATE * 100 spreadRate,
CHARGE_RATIO * 100 chargeRatio
from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO,
FIN_PRODUCT, FIN_PRODUCT_ADD
where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID =
FIN_CASH_INFO.CASH_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = 0
AND ((FIN_CASH_INFO.FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE != #{dealMode10})
OR (FIN_PRODUCT.P_FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode10}
AND FIN_PRODUCT_ADD.TERM_TYPE != #{termType02}))
and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

	and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}

and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = (
select MAX(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE)
from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO, FIN_PRODUCT,
FIN_PRODUCT_ADD
where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = FIN_CASH_INFO.CASH_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = 0
and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE <= to_date(#{queryDate},
'yyyy-MM-dd')
AND ((FIN_CASH_INFO.FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE != #{dealMode10})
OR (FIN_PRODUCT.P_FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode10}
AND FIN_PRODUCT_ADD.TERM_TYPE != #{termType02}))
and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

	and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}

)
order by LEV

select LEV lev, BASE_RULE_ID baseRuleId, COEFFICIENT coefficient, SPREAD_RATE * 100 spreadRate, CHARGE_RATIO * 100 chargeRatio from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO, FIN_PRODUCT, FIN_PRODUCT_ADD where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = FIN_CASH_INFO.CASH_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} and FIN_CASH_INFO.BRANCH = 0 AND (FIN_CASH_INFO.FINPROD_ID = #{finprodId}) and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}
and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
and (FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})
order by LEV

SELECT FIN_FLOAT_CALC_RULE_DETAIL.LEV lev, FIN_FLOAT_CALC_RULE_DETAIL.SPREAD_RATE*100 spreadRate, FIN_FLOAT_CALC_RULE_DETAIL.BASE_RULE_ID baseRuleId, FIN_FLOAT_CALC_RULE_DETAIL.COEFFICIENT coefficient, FIN_FLOAT_CALC_RULE_DETAIL.CHARGE_RATIO*100 chargeRatio FROM FIN_FLOAT_CALC_RULE_DETAIL
FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
AND to_char(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'yyyy-MM-dd') = #{effDate}
ORDER BY FIN_FLOAT_CALC_RULE_DETAIL.LEV ASC

select FINPROD_ID finprodId, CDATE cdate, BONUS_MODE bonusMode, INTPAY_PERIOD intpayPeriod, RATE rate, FLOAT_FEE_PROPORTION floatFeeProportion, FIX_FEE_PROPORTION fixFeeProportion, TRUST_FEE_PROPORTION trustFeeProportion, ACT_YIELD actYield, FIRST_PRIN_AMT firstPrinAmt, SHARE_AMT shareAmt, CUST_PROFIT custProfit, TRUST_FEE trustFee, SALE_FEE saleFee, FIX_FEE fixFee, PROXY_FEE proxyFee, ADD_TAX addTax, FLOAT_FEE floatFee, OTHER_FEE otherFee, ACT_MID_INCOME actMidIncome, MONTH_ISSUE_PRINAMT monthIssuePrinamt, MONTH_DUE_PRINAMT monthDuePrinamt, MONTH_ISSUE_SHAREAMT monthIssueShareamt, MONTH_DUE_SHAREAMT monthDueShareamt from PRD_STANDING_BOOK where PRD_STANDING_BOOK.CDATE = to_date(#{queryDate},'yyyy-MM-dd') and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeProd} and FIN_PRODUCT.P_FINPROD_ID IS NULL and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} and PRD_SALE_PARAM.FIRST_SALE_VDATE <= to_date(#{queryDate}, 'yyyy-MM-dd')
and fin_product.PROFIT_TYPE = '02'
and FIN_PRODUCT.FINPROD_MARKET_ID in
#{item}
AND FIN_PRODUCT_ADD.ISSUE_STATUS IN
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
AND FIN_PRODUCT_ADD.RISK_LEVEL IN
#{item}
and FIN_PRODUCT.VDATE >= to_date(#{vdateStart}, 'yyyy-MM-dd')
and FIN_PRODUCT.VDATE <= to_date(#{vdateEnd}, 'yyyy-MM-dd')
and FIN_PRODUCT.MDATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')
and FIN_PRODUCT.MDATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')
and FIN_PRODUCT.PROFIT_TYPE = #{profitType}
and FIN_PRODUCT_ADD.PROFIT_FLAG in
#{item}
and FIN_PRODUCT.ISSUE_TYPE in
#{item}
and FIN_PRODUCT.OPERATION_TYPE in
#{item}
and FIN_PRODUCT_ADD.PORTFOLIO_ID in
#{item}
and FIN_PRODUCT.FINPROD_ID in
#{item}
and PA_FIN_PRODUCT.DEAL_MODE = #{handleMode}
and PRD_SALE_PARAM.FIRST_SALE_VDATE >= to_date(#{raiseStrDateStart}, 'yyyy-MM-dd')
and PRD_SALE_PARAM.FIRST_SALE_VDATE <= to_date(#{raiseStrDateEnd}, 'yyyy-MM-dd')
and PRD_SALE_PARAM.FIRST_SALE_MDATE >= to_date(#{raiseEndDateStart}, 'yyyy-MM-dd')
and PRD_SALE_PARAM.FIRST_SALE_MDATE <= to_date(#{raiseEndDateEnd}, 'yyyy-MM-dd')
and FIN_PRODUCT_ADD.INVEST_NATURE in
#{item}
and PA_FIN_PRODUCT.prod_Series = #{prodSeries}
and CHB_PRDRESIST_CODE.REG_CODE in
#{item}
AND ((instr(PRD_SALE_PARAM.INVESTOR_TYPE, #{investorType1}) > 0
or instr(PRD_SALE_PARAM.INVESTOR_TYPE, #{investorType2}) > 0
or instr(PRD_SALE_PARAM.INVESTOR_TYPE, #{investorType3}) > 0
or instr(PRD_SALE_PARAM.INVESTOR_TYPE, #{investorType4}) > 0
or instr(PRD_SALE_PARAM.INVESTOR_TYPE, #{investorType5}) > 0
)
or exists (select PRD_LAYER_PARAM.FINPROD_ID from PRD_LAYER_PARAM WHERE PRD_LAYER_PARAM.P_FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND (instr(PRD_LAYER_PARAM.TAR_CUSTOMER_TYPE, #{investorType1}) > 0
or instr(PRD_LAYER_PARAM.TAR_CUSTOMER_TYPE, #{investorType2}) > 0
or instr(PRD_LAYER_PARAM.TAR_CUSTOMER_TYPE, #{investorType3}) > 0
or instr(PRD_LAYER_PARAM.TAR_CUSTOMER_TYPE, #{investorType4}) > 0
or instr(PRD_LAYER_PARAM.TAR_CUSTOMER_TYPE, #{investorType5}) > 0
)))
)
where durationflag IN
#{item}
order by finprodMarketId
